import { app, BrowserWindow, dialog } from "electron";
import path from "node:path";
import { fileURLToPath } from "node:url";
import process from "node:process";
import { spawn } from "node:child_process";
import fs from "node:fs";

// Early logging to console for debugging startup
console.log("[Main] Starting Electron app...");

// Allow forcing dev/prod logic via env for debugging packaged build locally
const forceProd = process.env.FORCE_PROD === "1";
const forceDev = process.env.FORCE_DEV === "1";
const isDev = forceDev || (!app.isPackaged && !forceProd);
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Simple logger stub (will be replaced after app.whenReady with file logger)
let log = (...args) => {
  try {
    // Keep console logging even before file logger is ready
    console.log(...args);
  } catch (_) {
    void _; // suppress unused variable lint
    // no-op
  }
};

// Keep reference to the spawned backend so we can terminate it on exit
let backendChild = null;

function createWindow() {
  console.log("[Main] createWindow called");
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    backgroundColor: "#0f1115",
    // Show window immediately to avoid "nothing opens" perception even if load is slow
    show: true,
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      // TODO: Re-enable sandbox after verifying preload remains compatible
      sandbox: false,
      devTools: isDev,
      spellcheck: false,
    },
  });

  // Center and focus the window
  win.center();
  win.focus();

  // Security: block navigation attempts
  win.webContents.on("will-navigate", (e, navUrl) => {
    if (navUrl !== win.webContents.getURL()) {
      e.preventDefault();
    }
  });
  win.webContents.setWindowOpenHandler(() => ({ action: "deny" }));

  const loadApp = async () => {
    log("[Main] createWindow -> loadApp start, isDev=", String(isDev));
    if (isDev) {
      await win.loadURL("http://localhost:5173");
    } else {
      const indexPath = path.join(__dirname, "../dist/index.html");
      try {
        await win.loadFile(indexPath);
      } catch (err) {
        log(
          "[Main] Failed to load index.html:",
          indexPath,
          String(err?.message || err)
        );
        dialog.showMessageBox(null, {
          message: "Load error: " + String(err?.message || err),
          type: "error",
        });
      }
    }
    if (isDev) {
      win.webContents.openDevTools({ mode: "detach" });
    }
    win.once("ready-to-show", () => {
      try {
        win.show();
      } catch (e) {
        void e; // suppress unused variable lint
        // ignore show errors (e)
      }
    });
  };
  loadApp();
}

// Ensure single instance (prevents multiple updaters and data races)
const gotLock = app.requestSingleInstanceLock();
if (!gotLock) {
  app.quit();
} else {
  app.on("second-instance", () => {
    const win = BrowserWindow.getAllWindows()[0];
    if (win) {
      if (win.isMinimized()) win.restore();
      win.focus();
    }
  });
}

app.whenReady().then(async () => {
  console.log("[Main] app.whenReady fired");
  // Sets correct AppUserModelID for notifications / taskbar grouping on Windows
  app.setAppUserModelId("com.pharmstore.app");
  // Simple file logger
  const logsDir = path.join(app.getPath("userData"), "logs");
  try {
    fs.mkdirSync(logsDir, { recursive: true });
  } catch (e) {
    void e; // suppress unused variable lint
    // ignore mkdir error (e)
  }
  const logFile = path.join(logsDir, "main.log");
  log = (...args) => {
    const line = `[${new Date().toISOString()}] ${args.map(String).join(" ")}`;
    try {
      fs.appendFileSync(logFile, line + "\n");
    } catch (e) {
      void e; // suppress unused variable lint
      // ignore append error (e)
    }
    try {
      console.log(...args);
    } catch (_) {
      void _; // suppress unused variable lint
      // ignore
    }
  };
  log(
    "[Main] starting",
    JSON.stringify({ isDev, resourcesPath: process.resourcesPath })
  );
  // Register a safe app protocol for CORS-less access to packaged assets
  // protocol.registerSchemesAsPrivileged([
  //   {
  //     scheme: "app",
  //     privileges: { standard: true, secure: true, supportFetchAPI: true },
  //   },
  // ]);

  // If packaged, spawn the backend server bundled under resources/backend
  if (!isDev) {
    try {
      const resources = process.resourcesPath;
      // Backend is packaged into resources/backend via extraResources
      const candidateDirs = [path.join(resources, "backend")];
      let backendDir = candidateDirs.find((p) => {
        try {
          return fs.existsSync(path.join(p, "index.js"));
        } catch (_) {
          void _; // suppress unused variable lint
          return false;
        }
      });
      if (!backendDir) {
        // Fallback: in case running unpackaged locally with FORCE_PROD
        const localCandidate = path.join(
          path.dirname(__dirname),
          "..",
          "backend"
        );
        if (fs.existsSync(path.join(localCandidate, "index.js"))) {
          backendDir = localCandidate;
        }
      }
      const backendIndex = backendDir
        ? path.join(backendDir, "index.js")
        : path.join(resources, "backend", "index.js");
      // Load backend config from packaged file and allow user override from userData path
      const packagedCfgPath = path.join(
        path.dirname(__dirname),
        "backend.config.json"
      );
      const userCfgPath = path.join(
        app.getPath("userData"),
        "backend.config.json"
      );
      // Create a user config template if missing
      try {
        if (!fs.existsSync(userCfgPath)) {
          const defaultCfg = {
            port: 3000,
            env: {
              NODE_ENV: "production",
              PORT: "3000",
              MONGO_URL: "mongodb://127.0.0.1:27017/pharmstore",
              SECRET: "desktop-build-secret",
              FRONTEND_ORIGINS:
                "app://-,http://localhost:5173,http://127.0.0.1:5173",
              // Optional: MongoDB Atlas sync
              // Set MONGO_ATLAS_URL to your Atlas connection string to enable manual sync
              // Example: "mongodb+srv://user:pass@cluster0.mongodb.net/pharmstore"
              MONGO_ATLAS_URL: "",
              // Set to "1" to enable background sync; requires MONGO_ATLAS_URL
              ATLAS_SYNC_BACKGROUND: "0",
              // Background sync interval in milliseconds (default 300000 = 5 minutes)
              ATLAS_SYNC_INTERVAL_MS: "300000",
            },
          };
          try {
            fs.writeFileSync(userCfgPath, JSON.stringify(defaultCfg, null, 2));
            log("[Main] Wrote user backend config template at", userCfgPath);
          } catch (e) {
            log(
              "[Main] Failed to write user backend config template:",
              e.message
            );
          }
        }
      } catch (e) {
        log("[Main] Error ensuring user backend config:", e.message);
      }
      let env = { ...process.env };
      const applyCfg = (cfgFile, label) => {
        try {
          if (!fs.existsSync(cfgFile)) return;
          const raw = fs.readFileSync(cfgFile, "utf-8");
          const json = JSON.parse(raw);
          if (json.env) env = { ...env, ...json.env };
          if (json.port && !json.env?.PORT) env.PORT = String(json.port);
          log("[Main] Applied backend config from", label, cfgFile);
        } catch (e) {
          log(
            "[Main] Failed reading",
            label,
            "backend.config.json:",
            e.message
          );
        }
      };
      applyCfg(packagedCfgPath, "packaged");
      applyCfg(userCfgPath, "userData");
      const exists = backendDir && fs.existsSync(backendIndex);
      log("[Main] backend index exists:", String(exists), "at", backendIndex);
      if (exists) {
        // Prefer local node if available next to backend (e.g., portable), otherwise use Electron's Node
        const localNode = path.join(backendDir, "node.exe");
        const exec = fs.existsSync(localNode) ? localNode : process.execPath;
        const envRun = fs.existsSync(localNode)
          ? env
          : { ...env, ELECTRON_RUN_AS_NODE: "1" };
        log(
          "[Main] spawning backend:",
          exec,
          backendIndex,
          "PORT=",
          envRun.PORT,
          "MONGO_URL set=",
          Boolean(envRun.MONGO_URL)
        );
        backendChild = spawn(exec, [backendIndex], {
          cwd: backendDir,
          env: envRun,
          stdio: ["ignore", "pipe", "pipe"],
          detached: false,
        });
        try {
          backendChild.stdout?.on("data", (d) =>
            log(`[Backend] ${String(d).trim()}`)
          );
          backendChild.stderr?.on("data", (d) =>
            log(`[Backend:err] ${String(d).trim()}`)
          );
          backendChild.on("error", (e) =>
            log("[Main] backend spawn error:", e.message)
          );
          backendChild.on("exit", (code, signal) => {
            log("[Main] backend exited:", String(code), String(signal || ""));
            // Inform the user that backend is not running (common cause: MongoDB not available)
            try {
              const msg =
                "The built-in API server stopped running.\n\n" +
                "Most common cause: MongoDB is not running or MONGO_URL is invalid.\n\n" +
                "Fix options:\n" +
                "1) Start MongoDB locally (default: mongodb://127.0.0.1:27017).\n" +
                "2) Or edit backend.config.json at: " +
                userCfgPath +
                "\n   and set env.MONGO_URL to a reachable MongoDB URI, then restart the app.";
              dialog.showMessageBox({
                type: "error",
                title: "Backend stopped",
                message: msg,
              });
            } catch (_) {
              void _; // ignore dialog errors
            }
          });
        } catch (e) {
          void e; // suppress unused variable lint
          // ignore spawn hook error (e)
        }
      } else {
        log("[Main] Packaged backend not found at", backendIndex);
      }
    } catch (e) {
      log("[Main] Failed to start packaged backend:", e.message);
    }
  }
  createWindow();

  // Global error logging to help diagnose blank screen issues
  process.on("uncaughtException", (e) => {
    try {
      fs.appendFileSync(
        path.join(app.getPath("userData"), "logs", "main.log"),
        `[uncaughtException] ${e?.stack || e?.message}\n`
      );
    } catch (w) {
      void w; // suppress unused variable lint
      // ignore UE write error (w)
    }
    console.error("[Main] uncaughtException:", e);
  });
  process.on("unhandledRejection", (r) => {
    try {
      fs.appendFileSync(
        path.join(app.getPath("userData"), "logs", "main.log"),
        `[unhandledRejection] ${String(r)}\n`
      );
    } catch (w) {
      void w; // suppress unused variable lint
      // ignore UR write error (w)
    }
    console.error("[Main] unhandledRejection:", r);
  });
  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
  // Ensure we terminate the backend on app exit to prevent folder locking
  const killBackend = () => {
    if (!backendChild || backendChild.killed) return;
    try {
      const pid = backendChild.pid;
      log("[Main] Killing backend (pid)", String(pid));
      if (process.platform === "win32") {
        // Force kill process tree on Windows
        try {
          spawn("taskkill", ["/PID", String(pid), "/T", "/F"], {
            windowsHide: true,
            stdio: "ignore",
            detached: false,
          });
        } catch (e) {
          log("[Main] taskkill error:", String(e?.message || e));
        }
      } else {
        try {
          backendChild.kill("SIGTERM");
        } catch (e) {
          void e; // suppress unused variable lint
          // ignore
        }
      }
    } catch (_) {
      void _; // suppress unused variable lint
      // ignore
    }
  };
  app.on("before-quit", killBackend);
  app.on("will-quit", killBackend);
  app.on("quit", killBackend);
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") app.quit();
});
